type InspectionBatch = { id: string; status: string; inspectedQuantity: string; acceptedQuantity: string; conditionalQuantity: string; rejectedQuantity: string };
type InboundBatch = { id: string; inboundNo: string; quantity: string; status: string };
type PayableBatch = { id: string; amount: string; status: string };
type Receipt = { id: string; receiptNo: string; quantity: string; status?: string; remark?: string | null; receivedDate?: string; batchSequence?: number; extensionData?: { payable_status?: string; payable_amount?: string }; inspections?: InspectionBatch[]; rawMaterialInbounds?: InboundBatch[]; payableSources?: PayableBatch[] };
type PurchaseItem = { id: string; materialId: string; unitId: string; bomItemId?: string | null; supplierId?: string | null; expectedDate?: string | null; model?: string | null; quantity: string; unitPrice?: string; material?: { materialCode?: string; name?: string }; unit?: { name?: string }; supplier?: { name?: string | null } | null; receipts: Receipt[]; batchWorkflows?: Array<{ receiptId: string; receiptNo: string; batchSequence: number; receivedQuantity: string; inspections: InspectionBatch[]; inbounds: InboundBatch[]; payableSources: PayableBatch[] }> };
type PurchaseOrder = { id: string; purchaseOrderNo: string; orderNo: string; bomId: string; supplierId: string; status: string; currency: string; expectedDate?: string | null; totalAmount: string; extensionData?: { arrival_closed?: boolean; over_order?: boolean }; supplier?: { name: string }; items: PurchaseItem[] };
type Inspection = { id: string; orderNo: string; purchase_order_no?: string; status: string; batchSequence?: number; inspectedQuantity: string; acceptedQuantity: string; conditionalQuantity: string; rejectedQuantity: string; downstream_exists?: boolean; purchaseReceipt?: Receipt };
type Inbound = { id: string; inboundNo: string; orderNo: string; quantity: string; status: string; purchase_order_no?: string | null; receipt_no?: string | null; batch_sequence?: number | null; inspection_status?: string | null; incomingInspectionId?: string | null };
type PayableSource = { id: string; orderNo: string; amount: string; status: string; rawMaterialInbound?: { inboundNo?: string } };
type Reference = { id: string; name?: string; orderNo?: string; bomNo?: string; version?: number; materialCode?: string; supplierCode?: string; code?: string; isActive?: boolean; status?: string; salesOrderId?: string; defaultUnitId?: string; materialType?: string; specificationModel?: string | null; color?: string | null; contactName?: string | null; phone?: string | null; remark?: string | null };
type BomItem = { id?: string; materialId: string; materialName: string; model?: string | null; specificationModel?: string | null; color?: string | null; productionBatchBase?: string | null; baseUsage?: string | null; approvedUsage?: string | null; requiredQuantity: string; unit: string; unitId?: string | null; materialSnapshot: Record<string, unknown> };
type Bom = { id: string; orderNo: string; salesOrderId: string; status: string; version: number; items: BomItem[] };
type PurchaseDraftItem = { materialId: string; model: string; quantity: string; unitId: string; unitPrice: string; supplierId: string; expectedDate: string; bomItemId?: string; currentStock?: string };
type PurchaseDraft = { id?: string; orderNo: string; bomId: string; importBomItems: boolean; items: PurchaseDraftItem[] };
type DialogState = { title: string; fields: ActionField[]; submit: (values: Record<string, string>) => void };
const messageOf = (cause: unknown, fallback: string) => cause instanceof ApiClientError ? cause.message : fallback;
// 规格型号/颜色引用物料主数据：仅在“选择物料/导入BOM”时用主数据覆盖行值，
// 保存时不做任何回填，BOM 行上的人工修改不会被 material_snapshot 覆盖。
const masterSpecOf = (material?: Reference | null) => ({ specificationModel: material?.specificationModel ?? "", color: material?.color ?? "" });

export default function ProcurementPage() {
  const [orders, setOrders] = useState<PurchaseOrder[]>([]); const [inspections, setInspections] = useState<Inspection[]>([]); const [inbounds, setInbounds] = useState<Inbound[]>([]); const [payables, setPayables] = useState<PayableSource[]>([]);
  const [materials, setMaterials] = useState<Reference[]>([]); const [units, setUnits] = useState<Reference[]>([]); const [suppliers, setSuppliers] = useState<Reference[]>([]); const [boms, setBoms] = useState<Reference[]>([]); const [salesOrders, setSalesOrders] = useState<Reference[]>([]);
  const [query, setQuery] = useState(""); const [selected, setSelected] = useState<PurchaseOrder | null>(null); const [dialog, setDialog] = useState<DialogState | null>(null); const [categoryDialog, setCategoryDialog] = useState<DialogState | null>(null); const [materialDraft, setMaterialDraft] = useState<Record<string, string> | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [message, setMessage] = useState(""); const [materialPanelOpen, setMaterialPanelOpen] = useState(false);
  const [selectedBom, setSelectedBom] = useState<Bom | null>(null); const [bomItems, setBomItems] = useState<BomItem[]>([]); const [bomMaterialIndex, setBomMaterialIndex] = useState<number | null>(null);
  const [purchaseDraft, setPurchaseDraft] = useState<PurchaseDraft | null>(null); const [stockByMaterial, setStockByMaterial] = useState<Record<string, string>>({});
  async function load() { setLoading(true); setError(""); try { const [po, qc, ib, payable, ms, us, ss, bs, so] = await Promise.all([apiGet<PurchaseOrder[]>("/purchase-orders"), apiGet<Inspection[]>("/incoming-inspections"), apiGet<Inbound[]>("/raw-material-inbounds"), apiGet<PayableSource[]>("/payable-sources"), apiGet<Reference[]>("/materials"), apiGet<Reference[]>("/units"), apiGet<Reference[]>("/suppliers"), apiGet<Reference[]>("/boms"), apiGet<Reference[]>("/sales-orders")]); setOrders(po.data); setInspections(qc.data); setInbounds(ib.data); setPayables(payable.data); setMaterials(ms.data); setUnits(us.data); setSuppliers(ss.data); setBoms(bs.data); setSalesOrders(so.data); } catch (cause) { setError(messageOf(cause, "采购数据加载失败")); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  async function openPurchaseOrder(id: string) { setError(""); try { const result = await apiGet<PurchaseOrder>(`/purchase-orders/${id}`); setSelected(result.data); } catch (cause) { notifyError(messageOf(cause, "采购单详情加载失败")); } }
  const visible = useMemo(() => orders.filter((item) => !query || `${item.purchaseOrderNo} ${item.orderNo} ${item.status}`.toLowerCase().includes(query.toLowerCase())), [orders, query]);
  async function action(path: string, body?: unknown, success = "操作已完成", method: "POST" | "PATCH" = "POST") { setError(""); try { if (method === "PATCH") await apiRequest(path, { method, body: JSON.stringify(body) }); else await apiPost(path, body); notifySuccess(success); await load(); if (selected) { const detail = await apiGet<PurchaseOrder>(`/purchase-orders/${selected.id}`); setSelected(detail.data); } } catch (cause) { notifyError(messageOf(cause, "操作失败")); } }   function deleteMaterial(id: string) { setDialog({ title: "删除物料", fields: [{ name: "confirm", label: "确认删除该物料？（被 BOM 或采购单引用的物料会被拒绝删除）", required: true, placeholder: "输入 删除 确认" }], submit: async (v) => { if (v.confirm?.trim() !== "删除") throw new Error("请输入“删除”确认"); await apiRequest(`/materials/${id}`, { method: "DELETE" }); notifySuccess("物料已删除"); await load(); } }); }
  const activeMaterials = useMemo(() => materials.filter((item) => item.isActive !== false), [materials]);
  const materialOptions = activeMaterials.map((item) => ({ value: item.id, label: `${item.materialCode ?? item.code ?? ""} / ${item.name ?? "物料"}` })); const unitOptions = units.filter((item) => item.isActive !== false).map((item) => ({ value: item.id, label: item.name ?? item.id })); const supplierOptions = suppliers.filter((item) => item.isActive !== false).map((item) => ({ value: item.id, label: `${item.supplierCode ?? item.code ?? ""} / ${item.name ?? "供应商"}` }));
  function openUnit(parentDraft?: Record<string, string>) { setCategoryDialog({ title: "新建单位", fields: [{ name: "name", label: "单位名称", required: true }, { name: "remark", label: "备注", type: "textarea" }], submit: async (v) => { try { const result = await apiPost<Reference>("/units", { name: v.name, remark: v.remark || undefined }); setUnits((items) => [...items, result.data]); setMaterialDraft(null); notifySuccess("单位已创建"); openMaterial({ ...parentDraft, default_unit_id: result.data.id }); } catch (cause) { notifyError(messageOf(cause, "单位创建失败")); } } }); }
  function openSupplier() { setCategoryDialog({ title: "新建供应商", fields: [{ name: "supplier_code", label: "供应商编码", required: true }, { name: "name", label: "供应商名称", required: true }, { name: "contact_name", label: "联系人" }, { name: "phone", label: "联系电话" }, { name: "remark", label: "备注", type: "textarea" }], submit: async (v) => { setError(""); try { const result = await apiPost<Reference>("/suppliers", { ...v, contact_name: v.contact_name || undefined, phone: v.phone || undefined, remark: v.remark || undefined }); setSuppliers((items) => [...items.filter((item) => item.id !== result.data.id), result.data]); setCategoryDialog(null); notifySuccess("供应商已创建"); } catch (cause) { notifyError(messageOf(cause, "供应商创建失败")); } } }); }
  function editSupplier(item: Reference) { setDialog({ title: `编辑供应商：${item.name ?? item.supplierCode ?? item.id}`, fields: [{ name: "supplier_code", label: "供应商编码", required: true, defaultValue: item.supplierCode ?? item.code ?? "" }, { name: "name", label: "供应商名称", required: true, defaultValue: item.name ?? "" }, { name: "contact_name", label: "联系人", defaultValue: item.contactName ?? "" }, { name: "phone", label: "联系电话", defaultValue: item.phone ?? "" }, { name: "remark", label: "备注", type: "textarea", defaultValue: item.remark ?? "" }], submit: async (v) => { await action(`/suppliers/${item.id}`, { supplier_code: v.supplier_code, name: v.name, contact_name: v.contact_name || null, phone: v.phone || null, remark: v.remark || null }, "供应商已更新", "PATCH"); } }); }
  function deleteSupplier(id: string) { setDialog({ title: "删除供应商", fields: [{ name: "confirm", label: "确认删除该供应商？（被采购单引用的供应商会被拒绝删除）", required: true, placeholder: "输入 删除 确认" }], submit: async (v) => { if (v.confirm?.trim() !== "删除") throw new Error("请输入“删除”确认"); await apiRequest(`/suppliers/${id}`, { method: "DELETE" }); notifySuccess("供应商已删除"); await load(); } }); }
  function openMaterial(input?: Record<string, string> | unknown) { const draft = input && typeof input === "object" && "name" in input ? input as Record<string, string> : materialDraft ?? {}; if (selectedBom && bomItems.length) setBomMaterialIndex(bomItems.length - 1); setCategoryDialog({ title: "新建物料", fields: [{ name: "code_mode", label: "编码方式", type: "select", required: true, defaultValue: draft.code_mode || "auto", options: [{ value: "auto", label: "自动生成" }, { value: "manual", label: "手动填写" }] }, { name: "material_code", label: "物料编码", defaultValue: draft.material_code, placeholder: "自动生成时留空" }, { name: "name", label: "物料名称", required: true, defaultValue: draft.name }, { name: "specification_model", label: "规格型号", defaultValue: draft.specification_model }, { name: "color", label: "颜色", defaultValue: draft.color }, { name: "default_unit_id", label: "默认单位", type: "select", required: true, defaultValue: draft.default_unit_id, options: unitOptions }, { name: "material_type", label: "物料类型", type: "select", required: true, defaultValue: draft.material_type || "raw_material", options: [{ value: "raw_material", label: "原料" }, { value: "finished_product", label: "成品" }] }, { name: "remark", label: "备注", type: "textarea", defaultValue: draft.remark }], submit: async (v) => { setError(""); try { const result = await apiPost<Reference>("/materials", { ...v, material_code: v.material_code || undefined, specification_model: v.specification_model || undefined, color: v.color || undefined, material_type: v.material_type || "raw_material", remark: v.remark || undefined }); setMaterials((items) => [...items, result.data]); if (bomMaterialIndex !== null && selectedBom) { const material = result.data; updateBomItem(bomMaterialIndex, { materialId: material.id, materialName: material.name ?? "", ...masterSpecOf(material), materialSnapshot: material }); } setMaterialDraft(null); notifySuccess("物料已创建"); setCategoryDialog(null); } catch (cause) { notifyError(messageOf(cause, "物料创建失败")); } } }); }
  function editMaterial(item: Reference) { setCategoryDialog({ title: "编辑物料", fields: [{ name: "material_code", label: "物料编码", required: true, defaultValue: item.materialCode ?? item.code ?? "" }, { name: "name", label: "物料名称", required: true, defaultValue: item.name ?? "" }, { name: "specification_model", label: "规格型号", defaultValue: item.specificationModel ?? "" }, { name: "color", label: "颜色", defaultValue: item.color ?? "" }, { name: "default_unit_id", label: "默认单位", type: "select", required: true, defaultValue: item.defaultUnitId, options: unitOptions }, { name: "material_type", label: "物料类型", type: "select", required: true, defaultValue: item.materialType ?? "raw_material", options: [{ value: "raw_material", label: "原料" }, { value: "finished_product", label: "成品" }] }], submit: async (v) => { await apiRequest(`/materials/${item.id}`, { method: "PATCH", body: JSON.stringify({ ...v, specification_model: v.specification_model || null, color: v.color || null }) }); setCategoryDialog(null); setMessage("物料已更新"); await load(); } }); }
  const materialColumns: ColumnDef<Reference>[] = [{ accessorKey: "materialCode", header: "物料编码" }, { accessorKey: "name", header: "物料名称" }, { accessorKey: "specificationModel", header: "规格型号", cell: ({ row }) => row.original.specificationModel ?? "-" }, { accessorKey: "color", header: "颜色", cell: ({ row }) => row.original.color ?? "-" }, { id: "unit", header: "默认单位", cell: ({ row }) => units.find((unit) => unit.id === row.original.defaultUnitId)?.name ?? "-" }, { id: "status", header: "状态", cell: ({ row }) => row.original.isActive === false ? "停用" : "启用" }, { id: "actions", header: "操作", cell: ({ row }) => <div className="action-row"><Button size="sm" variant="secondary" onClick={() => editMaterial(row.original)}>编辑</Button><Button size="sm" variant="ghost" onClick={() => void action(`/materials/${row.original.id}/active`, { is_active: row.original.isActive === false }, row.original.isActive === false ? "物料已启用" : "物料已停用")}>{row.original.isActive === false ? "启用" : "停用"}</Button><Button size="sm" variant="destructive" onClick={() => void deleteMaterial(row.original.id)}>删除</Button></div> }];
  const supplierColumns: ColumnDef<Reference>[] = [{ accessorKey: "supplierCode", header: "供应商编码" }, { accessorKey: "name", header: "供应商名称" }, { accessorKey: "contactName", header: "联系人", cell: ({ row }) => row.original.contactName ?? "-" }, { accessorKey: "phone", header: "联系电话", cell: ({ row }) => row.original.phone ?? "-" }, { accessorKey: "remark", header: "备注", cell: ({ row }) => row.original.remark ?? "-" }, { id: "status", header: "状态", cell: ({ row }) => row.original.isActive === false ? "停用" : "启用" }, { id: "actions", header: "操作", cell: ({ row }) => <div className="action-row"><Button size="sm" variant="secondary" onClick={() => editSupplier(row.original)}>编辑</Button><Button size="sm" variant="ghost" onClick={() => void action(`/suppliers/${row.original.id}/active`, { is_active: row.original.isActive === false }, row.original.isActive === false ? "供应商已启用" : "供应商已停用")}>{row.original.isActive === false ? "启用" : "停用"}</Button><Button size="sm" variant="destructive" onClick={() => deleteSupplier(row.original.id)}>删除</Button></div> }];
  function openReceipt() { const candidates = orders.filter((order) => ["ordered", "partially_arrived", "arrived_complete"].includes(order.status) && !order.extensionData?.arrival_closed && order.items.length); const itemOptions = candidates.flatMap((order) => order.items.map((item) => ({ value: item.id, label: `${order.purchaseOrderNo} / ${item.material?.materialCode ?? ""} ${item.material?.name ?? "物料"} / ${item.model || "未填写型号"} / 采购量 ${item.quantity}` }))); setDialog({ title: "新建到货记录", fields: [{ name: "purchase_order_id", label: "采购单", type: "select", required: true, options: candidates.map((order) => ({ value: order.id, label: `${order.purchaseOrderNo} / ${order.orderNo}` })) }, { name: "purchase_order_item_id", label: "采购物料", type: "select", required: true, options: itemOptions }, { name: "quantity", label: "到货数量", type: "number", required: true, defaultValue: "1" }, { name: "reference_no", label: "到货参考号" }, { name: "remark", label: "备注", type: "textarea" }], submit: async (v) => { await action(`/purchase-orders/${v.purchase_order_id}/items/${v.purchase_order_item_id}/receipts`, { quantity: v.quantity, received_date: new Date().toISOString(), reference_no: v.reference_no || undefined, remark: v.remark || undefined }, "到货记录已创建"); } }); }
  function addCategory(field: ActionField) { if (field.name === "supplier_id") openSupplier(); else if (field.name === "material_id") openMaterial(); else if (field.name === "unit_id" || field.name === "default_unit_id") openUnit(); else if (field.name === "receipt_id") openReceipt(); else setError(`${field.label}为业务记录，请在对应业务模块新建`); }
  async function openBom(id: string) { setError(""); try { const result = await apiGet<Bom>(`/boms/${id}`); setSelectedBom(result.data); setBomItems(result.data.items); } catch (cause) { notifyError(messageOf(cause, "BOM表加载失败")); } }
  async function createOrOpenBom(order: Reference) { const existing = boms.find((bom) => bom.salesOrderId === order.id); if (existing) { await openBom(existing.id); return; } setError(""); try { const result = await apiPost<Bom>(`/boms/from-sales-order/${order.id}`, { extension_data: {} }); setBoms((items) => [...items, result.data]); setSelectedBom(result.data); setBomItems(result.data.items); notifySuccess("BOM表已创建"); } catch (cause) { notifyError(messageOf(cause, "BOM表创建失败")); } }
  function updateBomItem(index: number, patch: Partial<BomItem>) { setBomItems((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item)); }
  function changeBomMaterial(index: number, materialId: string) { setBomMaterialIndex(index); const material = materials.find((item) => item.id === materialId); updateBomItem(index, { materialId, materialName: material?.name ?? "", ...masterSpecOf(material), materialSnapshot: material ?? {} }); }
  function addBomItem() { const material = materials.find((item) => item.isActive !== false && item.materialType === "raw_material"); setBomItems((items) => [...items, { materialId: material?.id ?? "", materialName: material?.name ?? "", model: "", ...masterSpecOf(material), productionBatchBase: "1", baseUsage: "1", requiredQuantity: "1", unit: "", materialSnapshot: material ?? {} }]); }
  async function saveBom() { if (!selectedBom) return; setError(""); try { const result = await apiRequest<Bom>(`/boms/${selectedBom.id}/items`, { method: "PUT", body: JSON.stringify({ items: bomItems.map((item) => ({ material_id: item.materialId, material_name: item.materialName, model: item.model || undefined, specification_model: item.specificationModel || undefined, color: item.color || undefined, production_batch_base: item.productionBatchBase || undefined, base_usage: item.baseUsage || undefined, material_snapshot: item.materialSnapshot, required_quantity: item.requiredQuantity, unit: item.unit, unit_id: item.unitId || undefined })) }) }); setSelectedBom(result.data); setBomItems(result.data.items); notifySuccess("BOM表已保存"); await load(); } catch (cause) { notifyError(messageOf(cause, "BOM表保存失败")); } }
  async function refreshMaterialStock(ids: string[]) { if (!ids.length) return; try { const result = await apiGet<Array<{ material_id: string; unit_id: string; quantity: string }>>(`/inventory/raw-material-balances?material_ids=${ids.join(",")}`); const stock = result.data.reduce<Record<string, string>>((acc, item) => { const key = `${item.material_id}|${item.unit_id}`; acc[key] = item.quantity; acc[item.material_id] = (Number(acc[item.material_id] ?? 0) + Number(item.quantity)).toString(); return acc; }, {}); setStockByMaterial(stock); } catch { /* inventory access is optional while drafting */ } }
  function createPurchaseOrder() { setPurchaseDraft({ orderNo: "", bomId: "", importBomItems: true, items: [] }); void refreshMaterialStock(materials.map((item) => item.id)); }
  function stockFor(materialId: string, unitId: string) { return stockByMaterial[`${materialId}|${unitId}`] ?? "0"; }
  function addPurchaseItem() { const material = materials.find((item) => item.isActive !== false); const unitId = material?.defaultUnitId ?? ""; setPurchaseDraft((draft) => draft ? { ...draft, items: [...draft.items, { materialId: material?.id ?? "", model: "", quantity: "1", unitId, unitPrice: "0", supplierId: "", expectedDate: "", currentStock: stockFor(material?.id ?? "", unitId) }] } : draft); }
  function updatePurchaseItem(index: number, patch: Partial<PurchaseDraftItem>) { setPurchaseDraft((draft) => draft ? { ...draft, items: draft.items.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) } : draft); }
  function changePurchaseMaterial(index: number, materialId: string) { const material = materials.find((item) => item.id === materialId); updatePurchaseItem(index, { materialId, unitId: material?.defaultUnitId ?? "" }); }
  async function importBomItems(bomId: string) { const bom = await apiGet<Bom>(`/boms/${bomId}`); const stock = await apiGet<Array<{ material_id: string; unit_id: string; quantity: string }>>(`/inventory/raw-material-balances?material_ids=${bom.data.items.map((item) => item.materialId).join(",")}`); const stockMap = stock.data.reduce<Record<string, string>>((acc, item) => { acc[`${item.material_id}|${item.unit_id}`] = item.quantity; acc[item.material_id] = (Number(acc[item.material_id] ?? 0) + Number(item.quantity)).toString(); return acc; }, {}); setStockByMaterial((current) => ({ ...current, ...stockMap })); setPurchaseDraft((draft) => draft ? { ...draft, items: bom.data.items.map((item) => { const unitId = item.unitId ?? units.find((unit) => unit.name === item.unit)?.id ?? ""; return { materialId: item.materialId, model: item.model || item.specificationModel || "", quantity: item.requiredQuantity, unitId, unitPrice: "0", supplierId: "", expectedDate: "", bomItemId: item.id, currentStock: stockMap[`${item.materialId}|${unitId}`] ?? "0" }; }) } : draft); }
  async function selectPurchaseBom(bomId: string) { setPurchaseDraft((draft) => draft ? { ...draft, bomId } : draft); if (purchaseDraft?.importBomItems && bomId) { try { await importBomItems(bomId); } catch (cause) { notifyError(messageOf(cause, "BOM表明细带入失败")); } } }
  async function toggleBomImport(enabled: boolean) { setPurchaseDraft((draft) => draft ? { ...draft, importBomItems: enabled, items: enabled ? draft.items : [] } : draft); if (enabled && purchaseDraft?.bomId) { try { await importBomItems(purchaseDraft.bomId); } catch (cause) { notifyError(messageOf(cause, "BOM表明细带入失败")); } } }
  async function editPurchaseOrder(id: string) { setError(""); try { const result = await apiGet<PurchaseOrder>(`/purchase-orders/${id}`); const order = result.data; setPurchaseDraft({ id: order.id, orderNo: order.orderNo, bomId: order.bomId, importBomItems: false, items: order.items.map((item) => ({ materialId: item.materialId, model: item.model ?? "", quantity: item.quantity, unitId: item.unitId, unitPrice: item.unitPrice ?? "0", supplierId: item.supplierId ?? order.supplierId ?? "", expectedDate: item.expectedDate?.slice(0, 10) ?? order.expectedDate?.slice(0, 10) ?? "", bomItemId: item.bomItemId ?? undefined })) }); } catch (cause) { setError(messageOf(cause, "采购单加载失败")); } }
  async function savePurchaseOrder() { if (!purchaseDraft) return; const missingSupplier = purchaseDraft.items.findIndex((item) => !item.supplierId); if (missingSupplier >= 0) { setError(`第 ${missingSupplier + 1} 行明细请选择供应商`); return; } const missingDate = purchaseDraft.items.findIndex((item) => !item.expectedDate); if (missingDate >= 0) { setError(`第 ${missingDate + 1} 行明细请填写预计到货日期`); return; } setError(""); try { const payload = { order_no: purchaseDraft.orderNo, bom_id: purchaseDraft.bomId, purchase_date: new Date().toISOString(), currency: "USD", items: purchaseDraft.items.map((item) => ({ material_id: item.materialId, model: item.model || undefined, unit_id: item.unitId, bom_item_id: item.bomItemId, supplier_id: item.supplierId, expected_date: item.expectedDate ? new Date(item.expectedDate).toISOString() : undefined, quantity: item.quantity, unit_price: item.unitPrice })) }; await (purchaseDraft.id ? apiRequest(`/purchase-orders/${purchaseDraft.id}`, { method: "PATCH", body: JSON.stringify(payload) }) : apiPost("/purchase-orders", payload)); setPurchaseDraft(null); notifySuccess(purchaseDraft.id ? "采购草稿已更新" : "采购草稿已创建"); await load(); } catch (cause) { setError(messageOf(cause, purchaseDraft.id ? "采购单更新失败" : "采购单创建失败")); } }
  function receive(order: PurchaseOrder, selectedItem?: PurchaseItem) { const item = selectedItem ?? order.items.find((candidate) => Number(candidate.quantity) > candidate.receipts.reduce((sum, row) => sum + Number(row.quantity), 0)) ?? order.items[0]; if (!item) return; const nextBatch = item.receipts.length + 1; setDialog({ title: `登记到货：${order.purchaseOrderNo} / ${item.material?.name ?? "物料"}（第 ${nextBatch} 批）`, fields: [{ name: "quantity", label: "本批到货数量", type: "number", required: true, defaultValue: "1" }, { name: "reference_no", label: "到货参考号" }, { name: "over_receipt_reason", label: "超收原因（超出采购量时必填）" }, { name: "remark", label: "备注", type: "textarea" }], submit: (v) => void action(`/purchase-orders/${order.id}/items/${item.id}/receipts`, { quantity: v.quantity, received_date: new Date().toISOString(), reference_no: v.reference_no || undefined, over_receipt_reason: v.over_receipt_reason || undefined, idempotency_key: `web-receipt-${Date.now()}-${Math.random().toString(36).slice(2)}`, remark: v.remark || undefined }, "到货记录已登记") }); }
  function editReceipt(receipt: Receipt) { setDialog({ title: `编辑到货批次：${receipt.receiptNo}`, fields: [{ name: "quantity", label: "到货数量", type: "number", required: true, defaultValue: receipt.quantity }, { name: "reference_no", label: "到货参考号" }, { name: "remark", label: "备注", type: "textarea", defaultValue: receipt.remark ?? undefined }, { name: "reason", label: "修改原因", type: "textarea", required: true }], submit: (v) => void action(`/purchase-orders/receipts/${receipt.id}`, { quantity: v.quantity, reference_no: v.reference_no || undefined, remark: v.remark || undefined, reason: v.reason }, "到货批次已更新", "PATCH") }); }
  function cancelReceipt(receipt: Receipt) { setDialog({ title: `撤销到货批次：${receipt.receiptNo}`, fields: [{ name: "reason", label: "撤销原因", type: "textarea", required: true }], submit: (v) => void action(`/purchase-orders/receipts/${receipt.id}/cancel`, { reason: v.reason }, "到货批次已撤销") }); }
  function inspect() { const receipts = orders.flatMap((order) => order.items.flatMap((item) => item.receipts.map((receipt, index) => ({ ...receipt, orderNo: order.orderNo, purchaseOrderNo: order.purchaseOrderNo, batchSequence: receipt.batchSequence ?? index + 1 })))); setDialog({ title: "登记来料质检", fields: [{ name: "receipt_id", label: "到货记录", type: "select", required: true, options: receipts.map((item) => ({ value: item.id, label: `${item.purchaseOrderNo} / 订单号 ${item.orderNo} / 第 ${item.batchSequence} 批 / ${item.quantity}` })) }, { name: "quantity", label: "送检数量", type: "number", required: true, defaultValue: "1" }, { name: "accepted_quantity", label: "合格数量", type: "number", required: true, defaultValue: "1" }, { name: "conditional_quantity", label: "条件接收", type: "number", required: true, defaultValue: "0" }, { name: "rejected_quantity", label: "不合格数量", type: "number", required: true, defaultValue: "0" }], submit: (v) => void action("/incoming-inspections", { purchase_receipt_id: v.receipt_id, inspected_quantity: v.quantity, accepted_quantity: v.accepted_quantity, conditional_quantity: v.conditional_quantity, rejected_quantity: v.rejected_quantity }, "来料质检 已记录") }); }
  function inspectReceipt(order: PurchaseOrder, item: PurchaseItem, receipt: Receipt) { const inspection = receipt.inspections?.[0]; const inspected = Number(inspection?.inspectedQuantity ?? 0); const remaining = Math.max(0, Number(receipt.quantity) - inspected); setDialog({ title: `登记来料质检：${order.purchaseOrderNo} / 第 ${receipt.batchSequence ?? "-"} 批`, fields: [{ name: "quantity", label: "本次送检数量", type: "number", required: true, defaultValue: remaining > 0 ? String(remaining) : "1" }, { name: "accepted_quantity", label: "本次合格数量", type: "number", required: true, defaultValue: remaining > 0 ? String(remaining) : "0" }, { name: "conditional_quantity", label: "本次条件接收", type: "number", required: true, defaultValue: "0" }, { name: "rejected_quantity", label: "本次不合格数量", type: "number", required: true, defaultValue: "0" }], submit: (v) => void action("/incoming-inspections", { purchase_receipt_id: receipt.id, inspected_quantity: v.quantity, accepted_quantity: v.accepted_quantity, conditional_quantity: v.conditional_quantity, rejected_quantity: v.rejected_quantity }, `第 ${receipt.batchSequence ?? "-"} 批质检已记录`) }); }
  function inboundInspection(order: PurchaseOrder, receipt: Receipt, inspection: InspectionBatch) { const allowed = Number(inspection.acceptedQuantity) + Number(inspection.conditionalQuantity); const used = (receipt.rawMaterialInbounds ?? []).reduce((sum, row) => sum + Number(row.quantity), 0); const remaining = Math.max(0, allowed - used); setDialog({ title: `创建原料入库：${order.purchaseOrderNo} / 第 ${receipt.batchSequence ?? "-"} 批`, fields: [{ name: "quantity", label: "本次入库数量", type: "number", required: true, defaultValue: remaining > 0 ? String(remaining) : "1" }, { name: "remark", label: "备注", type: "textarea" }], submit: (v) => void action("/raw-material-inbounds", { incoming_inspection_id: inspection.id, quantity: v.quantity, inventory_category: "raw_material", remark: v.remark || undefined }, `第 ${receipt.batchSequence ?? "-"} 批入库草稿已创建`) }); }
  function inbound() { setDialog({ title: "创建原料入库", fields: [{ name: "inspection_id", label: "质检记录", type: "select", required: true, options: inspections.map((item) => ({ value: item.id, label: `${item.purchase_order_no ?? "采购单待同步"} / 订单号 ${item.orderNo} / 第 ${item.batchSequence ?? item.purchaseReceipt?.batchSequence ?? "-"} 批 / ${item.inspectedQuantity} / ${item.status}` })) }, { name: "quantity", label: "入库数量", type: "number", required: true, defaultValue: "1" }, { name: "remark", label: "备注", type: "textarea" }], submit: (v) => void action("/raw-material-inbounds", { incoming_inspection_id: v.inspection_id, quantity: v.quantity, inventory_category: "raw_material", remark: v.remark || undefined }, "原料入库草稿已创建") }); }
  function transitionInspection(item: Inspection, target: string) { const needsReason = target === "pending" || target === "cancelled"; if (needsReason) { setDialog({ title: "回退来料质检", fields: [{ name: "reason", label: "回退原因", required: true, type: "textarea" }], submit: (v) => void action(`/incoming-inspections/${item.id}/status`, { target, reason: v.reason }, "来料质检状态已更新") }); return; } void action(`/incoming-inspections/${item.id}/status`, { target }, "来料质检状态已更新"); }
  function editInspection(item: Inspection) { setDialog({ title: `编辑来料质检：${item.purchase_order_no ?? item.orderNo}`, fields: [{ name: "inspected_quantity", label: "送检数量", type: "number", required: true, defaultValue: item.inspectedQuantity }, { name: "accepted_quantity", label: "合格数量", type: "number", required: true, defaultValue: item.acceptedQuantity }, { name: "conditional_quantity", label: "条件接收", type: "number", required: true, defaultValue: item.conditionalQuantity }, { name: "rejected_quantity", label: "不合格数量", type: "number", required: true, defaultValue: item.rejectedQuantity }, { name: "remark", label: "备注", type: "textarea" }, { name: "reason", label: "更正原因", type: "textarea", required: true }], submit: (v) => void action(`/incoming-inspections/${item.id}`, { inspected_quantity: v.inspected_quantity, accepted_quantity: v.accepted_quantity, conditional_quantity: v.conditional_quantity, rejected_quantity: v.rejected_quantity, remark: v.remark || undefined, reason: v.reason }, "来料质检已更新", "PATCH") }); }
  function reverseInbound(item: Inbound) { setDialog({ title: `冲销入库：${item.inboundNo}`, fields: [{ name: "reason", label: "冲销原因", required: true, type: "textarea" }], submit: (v) => void action(`/raw-material-inbounds/${item.id}/reverse`, { reason: v.reason }, "原料入库已冲销") }); }
  // 质检通过后的下游去向：全部入库 / 部分入库（可编辑数量）/ 整批退货。
  const inboundUsedByInspection = (inspectionId: string) => inbounds.filter((row) => row.incomingInspectionId === inspectionId && ["draft", "posted"].includes(row.status)).reduce((sum, row) => sum + Number(row.quantity), 0);
  const inboundRemainingFor = (item: Inspection) => Math.max(0, Number(item.acceptedQuantity) + Number(item.conditionalQuantity) - inboundUsedByInspection(item.id));
  const inspectionInboundCapable = (item: Inspection) => ["accepted", "conditionally_accepted", "partially_accepted", "completed"].includes(item.status) && item.status !== "cancelled";
  function inboundAll(item: Inspection) { const remaining = inboundRemainingFor(item); if (remaining <= 0) { setError("该质检批次没有可入库的剩余数量"); return; } void action("/raw-material-inbounds", { incoming_inspection_id: item.id, quantity: String(remaining), inventory_category: "raw_material" }, "原料入库草稿已创建"); }
  function inboundPartial(item: Inspection) { const remaining = inboundRemainingFor(item); setDialog({ title: `部分入库：${item.purchase_order_no ?? item.orderNo} / 第 ${item.batchSequence ?? "-"} 批`, fields: [{ name: "quantity", label: `本次入库数量（剩余可入 ${remaining}）`, type: "number", required: true, defaultValue: remaining > 0 ? String(remaining) : "1" }, { name: "remark", label: "备注", type: "textarea" }], submit: (v) => { const quantity = Number(v.quantity); if (!Number.isFinite(quantity) || quantity <= 0) { setError("入库数量必须是大于零的数字"); return; } if (quantity > remaining) { setError(`入库数量不能超过剩余可入数量 ${remaining}`); return; } void action("/raw-material-inbounds", { incoming_inspection_id: item.id, quantity: v.quantity, inventory_category: "raw_material", remark: v.remark || undefined }, "原料入库草稿已创建"); } }); }
  function returnInspection(item: Inspection) { setDialog({ title: `整批退货：${item.purchase_order_no ?? item.orderNo} / 第 ${item.batchSequence ?? "-"} 批`, fields: [{ name: "reason", label: "退货原因", required: true, type: "textarea" }], submit: (v) => void action(`/incoming-inspections/${item.id}/return`, { reason: v.reason }, "质检批次已退货") }); }
  function revertPurchaseOrder(order: PurchaseOrder) { setDialog({ title: `采购单回退草稿：${order.purchaseOrderNo}`, fields: [{ name: "reason", label: "回退原因", required: true, type: "textarea" }], submit: (v) => void action(`/purchase-orders/${order.id}/revert-draft`, { reason: v.reason }, "采购单已回到草稿") }); }
  function batchWorkflowRows(item: PurchaseItem) { return item.batchWorkflows ?? item.receipts.map((receipt, index) => ({ receiptId: receipt.id, receiptNo: receipt.receiptNo, batchSequence: receipt.batchSequence ?? index + 1, receivedQuantity: receipt.quantity, inspections: receipt.inspections ?? [], inbounds: receipt.rawMaterialInbounds ?? [], payableSources: receipt.payableSources ?? [] })); }
  // 到货批次信息按“物料 → 批次时间线”组织：每个物料一个小节，批次行只列该物料真实存在的批次，
  // 每列给出明确的业务含义（到货/质检/入库/应付），替代旧版按最大批次数铺开的全表矩阵。
  const inspectionStatusLabel: Record<string, string> = { pending: "待质检", inspecting: "质检中", completed: "已登记", accepted: "合格", conditionally_accepted: "条件接收", partially_accepted: "部分合格", rejected: "不合格", cancelled: "已取消" };
  const inboundStatusLabel: Record<string, string> = { draft: "草稿", posted: "已过账", reversed: "已冲销" };
  const payableStatusLabel: Record<string, string> = { pending_finance: "待财务确认", posted: "已过账", voided: "已作废" };
  function renderOrderBatchWorkflow(order: PurchaseOrder) {
    return <div className="purchase-item-blocks">{order.items.map((item) => {
      const rows = batchWorkflowRows(item);
      const materialLabel = `${item.material?.materialCode ?? ""} / ${item.material?.name ?? "物料"}${item.model ? ` / ${item.model}` : ""}`;
      const batches = rows.map((batch) => {
        const receipt = item.receipts.find((candidate) => candidate.id === batch.receiptId);
        const inspection = receipt?.inspections?.[0];
        const canInspect = Boolean(receipt) && receipt!.status !== "cancelled" && (!inspection || inspection.status === "pending" || (inspection.status === "partially_accepted" && !receipt!.rawMaterialInbounds?.length));
        const canInbound = Boolean(inspection) && ["accepted", "conditionally_accepted", "partially_accepted", "completed"].includes(inspection!.status);
        return <tr key={batch.receiptId}>
          <td>第 {batch.batchSequence} 批</td>
          <td>{receipt?.status === "cancelled" ? <span className="status-error">已撤销</span> : <>{batch.receivedQuantity}{receipt?.receivedDate ? <span className="batch-date"> · {receipt.receivedDate.slice(0, 10)}</span> : null}</>}</td>
          <td>{inspection ? <>{inspectionStatusLabel[inspection.status] ?? inspection.status} · 合格 {inspection.acceptedQuantity} · 条件 {inspection.conditionalQuantity} · 不合格 {inspection.rejectedQuantity}</> : <span className="batch-empty">待质检</span>}</td>
          <td>{batch.inbounds.length ? batch.inbounds.map((row) => `${row.quantity}（${inboundStatusLabel[row.status] ?? row.status}）`).join("、") : <span className="batch-empty">待入库</span>}</td>
          <td>{batch.payableSources.length ? batch.payableSources.map((source) => `${source.amount}（${payableStatusLabel[source.status] ?? source.status}）`).join("、") : <span className="batch-empty">待生成</span>}</td>
          <td><div className="action-row">{receipt && receipt.status !== "cancelled" && <><Button size="sm" variant="ghost" onClick={() => editReceipt(receipt)}>编辑到货</Button><Button size="sm" variant="ghost" onClick={() => cancelReceipt(receipt)}>撤销批次</Button></>}{canInspect && <Button size="sm" variant="ghost" onClick={() => inspectReceipt(order, item, receipt!)}>登记质检</Button>}{canInbound && <Button size="sm" variant="ghost" onClick={() => inboundInspection(order, receipt!, inspection!)}>登记入库</Button>}</div></td>
        </tr>;
      });
      return <div key={item.id} className="purchase-item-block">
        <div className="purchase-item-block-header">
          <span className="material-name-cell" title={materialLabel}>{materialLabel}</span>
          <span>采购数量 {item.quantity}{item.unit?.name ? ` ${item.unit.name}` : ""}</span>
          <span>供应商 {item.supplier?.name ?? "-"}</span>
          <span>预计到货 {item.expectedDate ? item.expectedDate.slice(0, 10) : "-"}</span>
          <Button size="sm" variant="secondary" onClick={() => receive(order, item)}>登记下一批到货</Button>
        </div>
        <div className="table-wrap"><table className="ui-table"><thead><tr><th className="ui-table-head">批次</th><th className="ui-table-head">到货</th><th className="ui-table-head">质检</th><th className="ui-table-head">入库</th><th className="ui-table-head">应付</th><th className="ui-table-head">操作</th></tr></thead><tbody>{batches.length ? batches : <tr><td>-</td><td><span className="batch-empty">尚未登记</span></td><td><span className="batch-empty">-</span></td><td><span className="batch-empty">-</span></td><td><span className="batch-empty">-</span></td><td><Button size="sm" variant="secondary" onClick={() => receive(order, item)}>登记到货</Button></td></tr>}</tbody></table></div>
      </div>;
    })}</div>;
  }
  const orderColumns: ColumnDef<PurchaseOrder>[] = [{ accessorKey: "purchaseOrderNo", header: "采购单号" }, { id: "orderNo", header: "订单号", cell: ({ row }) => <Button variant="link" onClick={() => void openPurchaseOrder(row.original.id)}>{row.original.orderNo}</Button> }, { id: "supplier", header: "供应商", cell: ({ row }) => row.original.supplier?.name ?? "-" }, { id: "status", header: "状态", cell: ({ row }) => { const totals = row.original.items.reduce((summary, item) => { summary.planned += Number(item.quantity); summary.received += item.receipts.reduce((sum, receipt) => sum + Number(receipt.quantity), 0); return summary; }, { planned: 0, received: 0 }); return totals.received > totals.planned ? <span className="status-error">超单</span> : totals.received === totals.planned && totals.planned > 0 ? <span className="status-success">到货完成</span> : row.original.status; } }, { id: "amount", header: "金额", cell: ({ row }) => `${row.original.totalAmount} ${row.original.currency}` }, { id: "actions", header: "操作", cell: ({ row }) => <div className="action-row">{row.original.status === "draft" && <><Button size="sm" variant="secondary" onClick={() => void editPurchaseOrder(row.original.id)}>编辑</Button><Button size="sm" variant="secondary" onClick={() => void action(`/purchase-orders/${row.original.id}/order`, undefined, "采购单已下单")}>下单</Button></>}{row.original.status === "ordered" && row.original.items.every((item) => item.receipts.length === 0) && <Button size="sm" variant="secondary" onClick={() => revertPurchaseOrder(row.original)}>回到草稿</Button>}{["ordered", "partially_arrived", "arrived_complete"].includes(row.original.status) && !row.original.extensionData?.arrival_closed && <Button size="sm" variant="secondary" onClick={() => void openPurchaseOrder(row.original.id)}>登记到货</Button>}{(() => { const complete = row.original.items.length > 0 && row.original.items.every((item) => item.receipts.reduce((sum, receipt) => sum + Number(receipt.quantity), 0) >= Number(item.quantity)); return complete && !row.original.extensionData?.arrival_closed ? <Button size="sm" onClick={() => void action(`/purchase-orders/${row.original.id}/close-arrivals`, undefined, "到货已关闭，批次已进入来料质检")}>关闭到货并进入质检</Button> : null; })()}</div> }];
  const inspectionColumns: ColumnDef<Inspection>[] = [{ accessorKey: "orderNo", header: "订单号" }, { accessorKey: "purchase_order_no", header: "采购单号", cell: ({ row }) => row.original.purchase_order_no ?? "-" }, { id: "batch", header: "质检批次", cell: ({ row }) => `第 ${row.original.batchSequence ?? row.original.purchaseReceipt?.batchSequence ?? "-"} 批` }, { accessorKey: "status", header: "状态" }, { accessorKey: "inspectedQuantity", header: "送检" }, { accessorKey: "acceptedQuantity", header: "合格" }, { accessorKey: "conditionalQuantity", header: "条件接收" }, { accessorKey: "rejectedQuantity", header: "不合格" }, { id: "actions", header: "操作", cell: ({ row }) => <div className="action-row">{!row.original.downstream_exists && row.original.status !== "cancelled" && <Button size="sm" variant="secondary" onClick={() => editInspection(row.original)}>编辑</Button>}{row.original.status === "pending" && <Button size="sm" variant="secondary" onClick={() => transitionInspection(row.original, "inspecting")}>开始质检</Button>}{row.original.status === "inspecting" && <Button size="sm" variant="secondary" onClick={() => transitionInspection(row.original, "completed")}>完成质检</Button>}{row.original.status === "completed" && <Button size="sm" variant="ghost" onClick={() => transitionInspection(row.original, "pending")}>回退</Button>}{inspectionInboundCapable(row.original) && <><Button size="sm" variant="secondary" onClick={() => inboundAll(row.original)}>全部入库</Button><Button size="sm" variant="secondary" onClick={() => inboundPartial(row.original)}>部分入库</Button>{!row.original.downstream_exists && <Button size="sm" variant="ghost" onClick={() => returnInspection(row.original)}>退货</Button>}</>}</div> }];
  function editInbound(item: Inbound) { setDialog({ title: "编辑原料入库单", fields: [{ name: "quantity", label: "入库数量", type: "number", required: true, defaultValue: item.quantity }, { name: "remark", label: "备注", type: "textarea" }], submit: (v) => void action(`/raw-material-inbounds/${item.id}`, { quantity: v.quantity, remark: v.remark || undefined }, "原料入库单已更新", "PATCH") }); }
  const inboundColumns: ColumnDef<Inbound>[] = [{ accessorKey: "inboundNo", header: "入库单号" }, { accessorKey: "orderNo", header: "订单号" }, { accessorKey: "purchase_order_no", header: "采购单号" }, { id: "batch", header: "到货批次", cell: ({ row }) => `第 ${row.original.batch_sequence ?? "-"} 批` }, { accessorKey: "receipt_no", header: "到货记录" }, { accessorKey: "quantity", header: "数量" }, { accessorKey: "inspection_status", header: "质检状态" }, { id: "status", header: "状态", cell: ({ row }) => row.original.status === "draft" ? <div className="action-row"><Button size="sm" variant="secondary" onClick={() => editInbound(row.original)}>编辑</Button><Button size="sm" variant="secondary" onClick={() => void action(`/raw-material-inbounds/${row.original.id}/post`, undefined, "原料入库已过账")}>过账</Button><Button size="sm" variant="ghost" onClick={() => void apiRequest(`/raw-material-inbounds/${row.original.id}`, { method: "DELETE" }).then(() => load())}>删除</Button></div> : row.original.status === "posted" ? <div className="action-row"><span>已过账</span><Button size="sm" variant="ghost" onClick={() => reverseInbound(row.original)}>冲销</Button></div> : row.original.status }, { id: "payable", header: "应付来源", cell: ({ row }) => payables.filter((source) => source.rawMaterialInbound?.inboundNo === row.original.inboundNo || (!source.rawMaterialInbound && source.orderNo === row.original.orderNo)).map((source) => `${source.amount}（${source.status}）`).join("、") || "待生成" }];
  const bomColumns: ColumnDef<Reference>[] = [{ accessorKey: "orderNo", header: "订单号" }, { accessorKey: "status", header: "订单状态" }, { id: "bom", header: "BOM表", cell: ({ row }) => { const bom = boms.find((item) => item.salesOrderId === row.original.id); return <Button size="sm" variant="secondary" onClick={() => void createOrOpenBom(row.original)}>{bom ? "编辑BOM表" : "新建BOM表"}</Button>; } }];
  if (loading) return <><PageHeader title="采购" /><LoadingState /></>;
  if (categoryDialog) return <ActionDialog open title={categoryDialog.title} fields={categoryDialog.fields} onOpenChange={(open) => { if (!open) setCategoryDialog(null); }} onAddCategory={(field, values) => { if (field.name === "default_unit_id") { setMaterialDraft(values); openUnit(values); } }} onSubmit={(values) => { void categoryDialog.submit(values); }} />;
  return <><PageHeader title="采购"><div className="page-actions"><Button onClick={createPurchaseOrder}>新建采购单</Button><Button variant="secondary" onClick={inspect}>登记质检</Button><Button variant="secondary" onClick={inbound}>原料入库</Button></div></PageHeader><ActionDialog open={Boolean(dialog)} onOpenChange={(open) => { if (!open) setDialog(null); }} title={dialog?.title ?? "操作"} fields={dialog?.fields ?? []} onAddCategory={addCategory} onSubmit={(values) => dialog?.submit(values)} />{message && <section className="panel panel-body status-success" role="status">{message}</section>}{error && <section className="panel"><ErrorState message={error} onRetry={() => void load()} /></section>}<section className="panel"><div className="panel-heading"><h2>物料清单</h2><div className="page-actions"><Button size="sm" variant="secondary" onClick={() => setMaterialPanelOpen(true)}>查看物料清单</Button></div></div><div className="panel-body"><p className="panel-note">物料主数据已收纳，点击上方按钮查看。</p></div></section><section className="panel"><div className="panel-heading"><h2>供应商池</h2><div className="page-actions"><Button size="sm" variant="secondary" onClick={openSupplier}>新建供应商</Button></div></div><div className="panel-body"><p className="panel-note">供应商主数据支持新增、编辑、停用、删除；采购单每行明细通过“供应商”列引用此处的供应商。</p><DataTable columns={supplierColumns} data={suppliers} empty={<EmptyState title="暂无供应商，点击“新建供应商”建立" />} /></div></section><section className="panel"><div className="panel-heading"><h2>BOM表</h2></div><div className="panel-body"><DataTable columns={bomColumns} data={salesOrders.filter((item) => item.status === "confirmed")} empty={<EmptyState title="暂无已确认销售单" />} /></div></section><section className="panel"><div className="panel-heading"><h2>采购单</h2></div><div className="panel-body"><div className="filter-bar"><label>按订单号搜索<Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="输入订单号" /></label></div><DataTable columns={orderColumns} data={visible} empty={<EmptyState title="暂无采购单" />} /></div></section>{selected && <section className="panel"><div className="panel-heading"><h2>订单详情：{selected.orderNo}</h2><Button variant="ghost" onClick={() => setSelected(null)}>返回订单列表</Button></div><div className="panel-body"><p>采购单：{selected.purchaseOrderNo}　供应商：{selected.supplier?.name ?? "-"}　状态：{selected.status}</p>{renderOrderBatchWorkflow(selected)}</div></section>}<section className="panel"><div className="panel-heading"><h2>来料质检</h2></div><div className="panel-body"><DataTable columns={inspectionColumns} data={inspections} empty={<EmptyState title="暂无待检批次" />} /></div></section><section className="panel"><div className="panel-heading"><h2>原料入库</h2></div><div className="panel-body"><DataTable columns={inboundColumns} data={inbounds} empty={<EmptyState title="暂无入库记录" />} /></div></section><Dialog open={materialPanelOpen} onOpenChange={setMaterialPanelOpen}><DialogContent className="material-library-dialog"><DialogHeader><DialogTitle>物料清单</DialogTitle><DialogDescription>统一维护物料主数据，BOM、采购和库存会共用这里的物料。</DialogDescription></DialogHeader><div className="page-actions"><Button size="sm" variant="secondary" onClick={openMaterial}>新建物料</Button></div><div className="table-wrap"><DataTable columns={materialColumns} data={materials} empty={<EmptyState title="暂无物料" />} /></div></DialogContent></Dialog><Sheet open={Boolean(selected)} onOpenChange={(open) => { if (!open) setSelected(null); }}><SheetContent className="purchase-batch-workspace"><SheetHeader><SheetTitle>{selected?.purchaseOrderNo}</SheetTitle><SheetDescription>采购单批次工作区：按物料比较各收货批次、质检、入库和应付状态。</SheetDescription></SheetHeader>{selected && <div className="detail-list"><p>订单号：{selected.orderNo}</p><p>供应商：{selected.supplier?.name ?? "-"}</p><p>状态：{selected.status}</p><p>金额：{selected.totalAmount} {selected.currency}</p>{renderOrderBatchWorkflow(selected)}{selected.items.map((item) => <div key={item.id}><p>明细：{item.quantity} / 到货 {item.receipts.reduce((sum, receipt) => sum + Number(receipt.quantity), 0)}</p>{item.receipts.length > 0 && <div className="table-wrap"><DataTable columns={[{ accessorKey: "receiptNo", header: "到货批次", cell: ({ row }) => `第 ${row.original.batchSequence ?? "-"} 批 / ${row.original.receiptNo}` }, { accessorKey: "quantity", header: "本批数量" }, { id: "payable", header: "应付", cell: ({ row }) => `${row.original.extensionData?.payable_amount ?? "0.0000"}（${row.original.extensionData?.payable_status ?? "待财务"}）` }]} data={item.receipts} /></div>}</div>)}</div>}</SheetContent></Sheet><Sheet open={Boolean(selectedBom)} onOpenChange={(open) => { if (!open) { setSelectedBom(null); setBomItems([]); } }}><SheetContent className="bom-workbench"><SheetHeader><SheetTitle>BOM表 {selectedBom?.orderNo}</SheetTitle><SheetDescription>物料名称、型号、规格型号、颜色、数量和单位可直接编辑；规格型号与颜色在选择物料或带入BOM时自动引用物料主数据，保存后保留人工修改。</SheetDescription></SheetHeader><div className="page-actions"><Button size="sm" variant="secondary" onClick={openMaterial}>新建物料</Button><Button size="sm" variant="secondary" onClick={addBomItem}>添加行</Button><Button size="sm" onClick={() => void saveBom()}>保存BOM表</Button></div><div className="table-wrap"><table className="data-table"><thead><tr><th>序号</th><th>物料名称</th><th>型号</th><th>规格型号</th><th>颜色</th><th>数量</th><th>单位</th><th><span className="sr-only">操作</span></th></tr></thead><tbody>{bomItems.map((item, index) => <tr key={item.id ?? `${item.materialId}-${index}`}><td>{index + 1}</td><td><Select value={item.materialId || undefined} onValueChange={(value) => changeBomMaterial(index, value)}><SelectTrigger><SelectValue placeholder="请选择物料" /></SelectTrigger><SelectContent>{materialOptions.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></td><td><Input value={item.model ?? ""} onChange={(event) => updateBomItem(index, { model: event.target.value })} /></td><td><Input value={item.specificationModel ?? ""} onChange={(event) => updateBomItem(index, { specificationModel: event.target.value })} /></td><td><Input value={item.color ?? ""} onChange={(event) => updateBomItem(index, { color: event.target.value })} /></td><td><Input type="number" min="0" step="0.0001" value={item.requiredQuantity} onChange={(event) => updateBomItem(index, { requiredQuantity: event.target.value })} /></td><td><Select value={item.unitId || undefined} onValueChange={(value) => updateBomItem(index, { unitId: value, unit: units.find((unit) => unit.id === value)?.name ?? value })}><SelectTrigger><SelectValue placeholder={item.unit || "选择单位"} /></SelectTrigger><SelectContent>{unitOptions.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></td><td><Button size="icon" variant="ghost" title="删除行" aria-label="删除行" onClick={() => setBomItems((items) => items.filter((_, itemIndex) => itemIndex !== index))}><Trash2 size={16} /></Button></td></tr>)}</tbody></table></div></SheetContent></Sheet><Sheet open={Boolean(purchaseDraft)} onOpenChange={(open) => { if (!open) setPurchaseDraft(null); }}><SheetContent className="material-issue-sheet purchase-workspace"><SheetHeader><SheetTitle>{purchaseDraft?.id ? "编辑采购单" : "新建采购单"}</SheetTitle><SheetDescription>绑定销售单和 BOM表后，在明细行逐行选择供应商和预计到货日期。</SheetDescription></SheetHeader>{purchaseDraft && <div className="detail-list"><label>销售单<Select value={purchaseDraft.orderNo || undefined} onValueChange={(value) => setPurchaseDraft({ ...purchaseDraft, orderNo: value, bomId: "", items: [] })}><SelectTrigger><SelectValue placeholder="请选择销售单" /></SelectTrigger><SelectContent>{salesOrders.filter((item) => item.status === "confirmed").map((item) => <SelectItem key={item.id} value={item.orderNo ?? item.id}>{item.orderNo ?? item.id}</SelectItem>)}</SelectContent></Select></label><label>BOM表<Select value={purchaseDraft.bomId || undefined} disabled={!purchaseDraft.orderNo} onValueChange={(value) => void selectPurchaseBom(value)}><SelectTrigger><SelectValue placeholder="请选择BOM表" /></SelectTrigger><SelectContent>{boms.filter((item) => item.orderNo === purchaseDraft.orderNo).map((item) => <SelectItem key={item.id} value={item.id}>{item.orderNo}</SelectItem>)}</SelectContent></Select></label><label><Button type="button" variant={purchaseDraft.importBomItems ? "secondary" : "ghost"} aria-pressed={purchaseDraft.importBomItems} onClick={() => void toggleBomImport(!purchaseDraft.importBomItems)}>带入 BOM表明细：{purchaseDraft.importBomItems ? "是" : "否"}</Button></label><div className="page-actions"><Button size="sm" variant="secondary" onClick={addPurchaseItem}>添加行</Button><Button size="sm" onClick={() => void savePurchaseOrder()}>保存采购单</Button></div><div className="table-wrap"><table className="data-table"><thead><tr><th>名称</th><th>型号</th><th>需求量</th><th>当前库存量</th><th>单位</th><th>单价</th><th>供应商</th><th>预计到货</th><th><span className="sr-only">操作</span></th></tr></thead><tbody>{purchaseDraft.items.map((item, index) => <tr key={`${item.materialId}-${index}`}><td><Select value={item.materialId || undefined} onValueChange={(value) => changePurchaseMaterial(index, value)}><SelectTrigger><SelectValue placeholder="请选择物料" /></SelectTrigger><SelectContent>{materialOptions.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></td><td><Input value={item.model} onChange={(event) => updatePurchaseItem(index, { model: event.target.value })} /></td><td><Input type="number" min="0" step="0.0001" value={item.quantity} onChange={(event) => updatePurchaseItem(index, { quantity: event.target.value })} /></td><td className={Number(stockByMaterial[item.materialId] ?? 0) >= Number(item.quantity) ? "stock-ok" : "stock-low"}>{stockByMaterial[item.materialId] ?? "0"}</td><td><Select value={item.unitId || undefined} onValueChange={(value) => updatePurchaseItem(index, { unitId: value })}><SelectTrigger><SelectValue placeholder="请选择单位" /></SelectTrigger><SelectContent>{unitOptions.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></td><td><Input type="number" min="0" step="0.0001" value={item.unitPrice} onChange={(event) => updatePurchaseItem(index, { unitPrice: event.target.value })} /></td><td><Select value={item.supplierId || undefined} onValueChange={(value) => updatePurchaseItem(index, { supplierId: value })}><SelectTrigger><SelectValue placeholder="请选择供应商" /></SelectTrigger><SelectContent>{supplierOptions.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></td><td><Input type="date" value={item.expectedDate} onChange={(event) => updatePurchaseItem(index, { expectedDate: event.target.value })} aria-label="预计到货日期" /></td><td><Button size="icon" variant="ghost" title="删除行" aria-label="删除行" onClick={() => setPurchaseDraft({ ...purchaseDraft, items: purchaseDraft.items.filter((_, itemIndex) => itemIndex !== index) })}><Trash2 size={16} /></Button></td></tr>)}</tbody></table></div></div>}</SheetContent></Sheet></>;
}

